// This throws ConcurrentModificationException -- single thread!
for (Map.Entry<String, Integer> entry : map.entrySet()) {
    if (entry.getValue() < 3) {
        map.remove(entry.getKey()); // Modifies map during iteration
    }
}

// Safe alternative using removeIf
map.entrySet().removeIf(entry -> entry.getValue() < 3);

package practice;

import java.util.Map;

public final class Scores {

    private Scores() {
    }

    /** Removes every entry scored below min, in place, and returns how many were removed. */
    public static int dropBelow(Map<String, Integer> scores, int min) {
        int before = scores.size();
        scores.entrySet().removeIf(entry -> entry.getValue() < min);
        return before - scores.size();
    }
}

